package com.fasterxml.jackson.core.util;

import com.fasterxml.jackson.core.*;
import org.junit.Test;
import static org.junit.Assert.*;

import java.io.IOException;

public class JsonParserDelegateTest {

    @Test
    public void testGetNumberTypeFPDefault() throws IOException {
        // Test the default implementation in JsonParser (via a concrete parser)
        JsonFactory factory = new JsonFactory();
        // Use a simple JSON with a floating point number
        try (JsonParser parser = factory.createParser("3.14")) {
            // Advance to the token
            assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.nextToken());
            // The default implementation should return UNKNOWN for textual JSON
            assertEquals(JsonParser.NumberTypeFP.UNKNOWN, parser.getNumberTypeFP());
        }
    }

    @Test
    public void testGetNumberTypeFPDelegate() throws IOException {
        JsonFactory factory = new JsonFactory();
        try (JsonParser parser = factory.createParser("2.718")) {
            JsonParserDelegate delegate = new JsonParserDelegate(parser);
            // Advance to the token
            assertEquals(JsonToken.VALUE_NUMBER_FLOAT, delegate.nextToken());
            // The delegate should return the same as the delegate parser
            // Since the underlying parser is a JSON parser, it should return UNKNOWN
            assertEquals(JsonParser.NumberTypeFP.UNKNOWN, delegate.getNumberTypeFP());
            // Also verify that the delegate's method returns the same as the wrapped parser
            assertEquals(parser.getNumberTypeFP(), delegate.getNumberTypeFP());
        }
    }

    @Test
    public void testGetNumberTypeFPNonFloat() throws IOException {
        // For non-float tokens, should return UNKNOWN
        JsonFactory factory = new JsonFactory();
        // Test with an integer token
        try (JsonParser parser = factory.createParser("42")) {
            assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
            // Even though it's a number, it's not a float, so should return UNKNOWN
            assertEquals(JsonParser.NumberTypeFP.UNKNOWN, parser.getNumberTypeFP());
        }
        // Test with a non-number token
        try (JsonParser parser = factory.createParser("\"string\"")) {
            assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
            assertEquals(JsonParser.NumberTypeFP.UNKNOWN, parser.getNumberTypeFP());
        }
    }

    @Test
    public void testNumberTypeFPEnumValues() {
        // Verify the enum constants exist
        JsonParser.NumberTypeFP[] values = JsonParser.NumberTypeFP.values();
        // There should be 5 constants: FLOAT16, FLOAT32, DOUBLE64, BIG_DECIMAL, UNKNOWN
        assertEquals(5, values.length);
        // Check each constant
        assertEquals(JsonParser.NumberTypeFP.FLOAT16, JsonParser.NumberTypeFP.valueOf("FLOAT16"));
        assertEquals(JsonParser.NumberTypeFP.FLOAT32, JsonParser.NumberTypeFP.valueOf("FLOAT32"));
        assertEquals(JsonParser.NumberTypeFP.DOUBLE64, JsonParser.NumberTypeFP.valueOf("DOUBLE64"));
        assertEquals(JsonParser.NumberTypeFP.BIG_DECIMAL, JsonParser.NumberTypeFP.valueOf("BIG_DECIMAL"));
        assertEquals(JsonParser.NumberTypeFP.UNKNOWN, JsonParser.NumberTypeFP.valueOf("UNKNOWN"));
    }
}

