package com.fasterxml.jackson.core.util;

import org.junit.Test;
import static org.junit.Assert.*;

public class TextBufferTest {

    @Test
    public void testGetTextBufferAfterResetWithEmpty() {
        // Create a TextBuffer with a BufferRecycler
        TextBuffer buffer = new TextBuffer(new BufferRecycler());

        // Reset the buffer to empty state
        buffer.resetWithEmpty();

        // Before the patch: getTextBuffer() returns null for empty buffer
        // After the patch: getTextBuffer() should return empty array []
        char[] result = buffer.getTextBuffer();

        // Assert that the result is not null (patch ensures it returns empty array)
        assertNotNull("getTextBuffer() should not return null after resetWithEmpty()", result);

        // Assert that the result is an empty array (length 0)
        assertEquals("getTextBuffer() should return empty array after resetWithEmpty()", 
                     0, result.length);

        // Verify consistency after calling contentsAsString()
        buffer.contentsAsString(); // This should not affect the buffer state
        char[] result2 = buffer.getTextBuffer();
        assertNotNull("getTextBuffer() should not return null after contentsAsString()", result2);
        assertEquals("getTextBuffer() should return empty array after contentsAsString()", 
                     0, result2.length);
    }

    @Test
    public void testGetTextBufferConsistency() {
        TextBuffer buffer = new TextBuffer(new BufferRecycler());
        buffer.resetWithEmpty();

        // First call to getTextBuffer() should return empty array
        char[] firstResult = buffer.getTextBuffer();
        assertNotNull(firstResult);
        assertEquals(0, firstResult.length);

        // Call contentsAsString() which returns empty string
        String str = buffer.contentsAsString();
        assertEquals("", str);

        // Second call to getTextBuffer() should still return empty array
        char[] secondResult = buffer.getTextBuffer();
        assertNotNull(secondResult);
        assertEquals(0, secondResult.length);

        // Both results should be the same instance (NO_CHARS)
        assertSame("Both calls should return the same NO_CHARS instance", 
                   firstResult, secondResult);
    }

    @Test
    public void testGetTextBufferWithNonEmptyBuffer() {
        TextBuffer buffer = new TextBuffer(new BufferRecycler());

        // Append some content to make buffer non-empty
        buffer.append("test", 0, 4);

        // getTextBuffer() should return non-null array with content
        char[] result = buffer.getTextBuffer();
        assertNotNull(result);
        assertTrue(result.length > 0);

        // Verify content
        assertEquals('t', result[0]);
        assertEquals('e', result[1]);
        assertEquals('s', result[2]);
        assertEquals('t', result[3]);
    }

    @Test
    public void testGetTextBufferAfterResetWithString() {
        TextBuffer buffer = new TextBuffer(new BufferRecycler());

        // Reset with empty string
        buffer.resetWithString("");

        // Should return empty array, not null
        char[] result = buffer.getTextBuffer();
        assertNotNull(result);
        assertEquals(0, result.length);

        // Reset with non-empty string
        buffer.resetWithString("hello");
        result = buffer.getTextBuffer();
        assertNotNull(result);
        assertEquals(5, result.length);
        assertEquals("hello", new String(result));
    }

    @Test
    public void testGetTextBufferWithSharedInputBuffer() {
        TextBuffer buffer = new TextBuffer(new BufferRecycler());
        char[] input = {'a', 'b', 'c'};

        // Set up shared input buffer
        buffer.resetWithShared(input, 0, 3);

        // Should return the input buffer directly
        char[] result = buffer.getTextBuffer();
        assertSame(input, result);
    }

    @Test
    public void testGetTextBufferWithResultString() {
        TextBuffer buffer = new TextBuffer(new BufferRecycler());

        // Manually set result string (simulating after contentsAsString())
        buffer.resetWithString("result");

        // First call converts to array
        char[] result1 = buffer.getTextBuffer();
        assertNotNull(result1);
        assertEquals("result", new String(result1));

        // Second call should return cached array
        char[] result2 = buffer.getTextBuffer();
        assertSame(result1, result2);
    }
}

