package com.fasterxml.jackson.core;

import org.junit.Test;
import static org.junit.Assert.*;

public class JsonPointerAppendTest {

    @Test
    public void testAppendWithTrailingSlash() {
        // Test case where current pointer ends with "/"
        JsonPointer base = JsonPointer.compile("/foo/");
        JsonPointer toAppend = JsonPointer.compile("/bar");

        // Before patch: append would keep the trailing slash, resulting in "/foo//bar"
        // After patch: trailing slash is removed before concatenation, resulting in "/foo/bar"
        JsonPointer result = base.append(toAppend);

        // Verify the result is correct after patch
        assertEquals("/foo/bar", result.toString());

        // Additional verification: check that the pointer works correctly
        assertTrue(result.matchesProperty("foo"));
        JsonPointer tail = result.tail();
        assertTrue(tail.matchesProperty("bar"));
    }

    @Test
    public void testAppendWithoutTrailingSlash() {
        // Test case where current pointer does NOT end with "/"
        JsonPointer base = JsonPointer.compile("/foo");
        JsonPointer toAppend = JsonPointer.compile("/bar");

        JsonPointer result = base.append(toAppend);

        // Should work the same before and after patch
        assertEquals("/foo/bar", result.toString());
    }

    @Test
    public void testAppendEmptyPointer() {
        // Test appending to empty pointer
        JsonPointer base = JsonPointer.compile("/");
        JsonPointer toAppend = JsonPointer.compile("/bar");

        JsonPointer result = base.append(toAppend);

        // Before patch: "/" + "/bar" = "//bar" (incorrect)
        // After patch: trailing slash removed, so "" + "/bar" = "/bar"
        assertEquals("/bar", result.toString());
    }

    @Test
    public void testAppendToRootPointer() {
        // Special case: root pointer "/"
        JsonPointer root = JsonPointer.compile("/");
        JsonPointer child = JsonPointer.compile("/baz");

        JsonPointer result = root.append(child);

        // Before patch: would result in "//baz"
        // After patch: should be "/baz"
        assertEquals("/baz", result.toString());

        // Verify it matches property "baz"
        assertTrue(result.matchesProperty("baz"));
    }

    @Test
    public void testAppendMultipleSegments() {
        // Test appending a pointer with multiple segments
        JsonPointer base = JsonPointer.compile("/a/b/");
        JsonPointer toAppend = JsonPointer.compile("/c/d");

        JsonPointer result = base.append(toAppend);

        // Before patch: "/a/b//c/d" (double slash)
        // After patch: "/a/b/c/d" (correct)
        assertEquals("/a/b/c/d", result.toString());

        // Verify structure
        JsonPointer current = result;
        assertTrue(current.matchesProperty("a"));
        current = current.tail();
        assertTrue(current.matchesProperty("b"));
        current = current.tail();
        assertTrue(current.matchesProperty("c"));
        current = current.tail();
        assertTrue(current.matchesProperty("d"));
        assertTrue(current.tail().matches());
    }

    @Test
    public void testAppendWithArrayIndex() {
        // Test with array indices
        JsonPointer base = JsonPointer.compile("/array/");
        JsonPointer toAppend = JsonPointer.compile("/0");

        JsonPointer result = base.append(toAppend);

        // Before patch: "/array//0"
        // After patch: "/array/0"
        assertEquals("/array/0", result.toString());

        // Verify it matches element 0
        assertTrue(result.tail().matchesElement(0));
    }

    @Test
    public void testAppendSpecialCharacters() {
        // Test with special characters that need escaping
        JsonPointer base = JsonPointer.compile("/path with spaces/");
        JsonPointer toAppend = JsonPointer.compile("/~0~1");

        JsonPointer result = base.append(toAppend);

        // Before patch: "/path with spaces//~0~1"
        // After patch: "/path with spaces/~0~1"
        assertEquals("/path with spaces/~0~1", result.toString());
    }

    @Test
    public void testAppendEmptyToEmpty() {
        // Edge case: appending empty to empty
        JsonPointer empty1 = JsonPointer.compile("");
        JsonPointer empty2 = JsonPointer.compile("");

        JsonPointer result = empty1.append(empty2);

        // Should result in empty pointer
        assertEquals("", result.toString());
        assertTrue(result.matches());
    }

    @Test
    public void testAppendChain() {
        // Test chaining multiple append operations
        JsonPointer p1 = JsonPointer.compile("/a/");
        JsonPointer p2 = JsonPointer.compile("/b/");
        JsonPointer p3 = JsonPointer.compile("/c");

        JsonPointer result = p1.append(p2).append(p3);

        // Before patch: "/a//b//c"
        // After patch: "/a/b/c"
        assertEquals("/a/b/c", result.toString());
    }

    @Test
    public void testAppendWithLastMethod() {
        // Test interaction with the new last() method from the same patch
        JsonPointer base = JsonPointer.compile("/parent/");
        JsonPointer leaf = JsonPointer.compile("/child");

        JsonPointer appended = base.append(leaf);
        JsonPointer last = appended.last();

        // Verify last() returns the correct leaf
        assertEquals("/child", last.toString());
        assertTrue(last.matchesProperty("child"));
    }
}

