package com.fasterxml.jackson.core.filter;

import org.junit.Test;
import static org.junit.Assert.*;

import java.lang.reflect.Method;

public class TokenFilterTest {

    // Helper class for testing
    static class IncludeEmptyArraysFilter extends TokenFilter {
        @Override
        public boolean includeEmptyArray(boolean contentsFiltered) {
            return true;
        }

        @Override
        public boolean includeEmptyObject(boolean contentsFiltered) {
            return true;
        }
    }

    @Test
    public void testIncludeEmptyArrayMethodExists() throws Exception {
        // This test will fail before the patch because the method does not exist.
        // After the patch, the method exists, so it will pass.
        Method m = TokenFilter.class.getMethod("includeEmptyArray", boolean.class);
        assertNotNull(m);
        assertEquals(boolean.class, m.getReturnType());
    }

    @Test
    public void testIncludeEmptyObjectMethodExists() throws Exception {
        Method m = TokenFilter.class.getMethod("includeEmptyObject", boolean.class);
        assertNotNull(m);
        assertEquals(boolean.class, m.getReturnType());
    }

    @Test
    public void testDefaultIncludeEmptyArrayReturnsFalse() {
        TokenFilter filter = new TokenFilter();
        assertFalse(filter.includeEmptyArray(false));
        assertFalse(filter.includeEmptyArray(true));
    }

    @Test
    public void testDefaultIncludeEmptyObjectReturnsFalse() {
        TokenFilter filter = new TokenFilter();
        assertFalse(filter.includeEmptyObject(false));
        assertFalse(filter.includeEmptyObject(true));
    }

    @Test
    public void testCustomFilterIncludeEmptyArray() {
        TokenFilter filter = new IncludeEmptyArraysFilter();
        assertTrue(filter.includeEmptyArray(false));
        assertTrue(filter.includeEmptyArray(true));
    }

    @Test
    public void testCustomFilterIncludeEmptyObject() {
        TokenFilter filter = new IncludeEmptyArraysFilter();
        assertTrue(filter.includeEmptyObject(false));
        assertTrue(filter.includeEmptyObject(true));
    }

    @Test
    public void testIncludeAllConstantHasDefaultBehavior() {
        // INCLUDE_ALL should use default behavior (return false for empty arrays/objects)
        assertFalse(TokenFilter.INCLUDE_ALL.includeEmptyArray(false));
        assertFalse(TokenFilter.INCLUDE_ALL.includeEmptyArray(true));
        assertFalse(TokenFilter.INCLUDE_ALL.includeEmptyObject(false));
        assertFalse(TokenFilter.INCLUDE_ALL.includeEmptyObject(true));
    }
}

