    public void testIncludeEmptyArrayParsing() throws IOException {
        JsonFactory f = new JsonFactory();
        String json = "{\"a\":[]}";
        JsonParser p = f.createParser(json);
        TokenFilter filter = new IncludeEmptyArraysFilter();
        FilteringParserDelegate delegate = new FilteringParserDelegate(p, filter, true, false);

        // Collect tokens
        java.util.List<JsonToken> tokens = new java.util.ArrayList<JsonToken>();
        while (delegate.nextToken() != null) {
            tokens.add(delegate.getCurrentToken());
        }

        // Before patch: tokens would be [START_OBJECT, FIELD_NAME, END_OBJECT] (array skipped)
        // After patch: tokens should be [START_OBJECT, FIELD_NAME, START_ARRAY, END_ARRAY, END_OBJECT]
        // We assert that START_ARRAY and END_ARRAY are present.
        boolean foundStartArray = false;
        boolean foundEndArray = false;
        for (JsonToken t : tokens) {
            if (t == JsonToken.START_ARRAY) foundStartArray = true;
            if (t == JsonToken.END_ARRAY) foundEndArray = true;
        }
        assertTrue("START_ARRAY not found in tokens: " + tokens, foundStartArray);
        assertTrue("END_ARRAY not found in tokens: " + tokens, foundEndArray);
        // Also verify the order? Not necessary for this test.
    }

    @Test
    public void testIncludeEmptyArrayGeneration() throws IOException {
        // Create a TokenFilterContext tree.
        TokenFilter filter = new IncludeEmptyArraysFilter();
        // Create root context (type doesn't matter, but we need one)
        TokenFilterContext root = TokenFilterContext.createRootContext(filter);
        // Create a child array context. We need to simulate that the array start was not handled.
        // The method createChildArrayContext takes (filter, startHandled).
        // We want startHandled = false to trigger the empty array writing.
        TokenFilterContext child = root.createChildArrayContext(filter, false);
        // Now close the array with a JsonGenerator.
        StringWriter sw = new StringWriter();
        JsonGenerator gen = new JsonFactory().createGenerator(sw);
        // We need to set the current name? For array, it uses hasCurrentIndex().
        // Since we haven't advanced, hasCurrentIndex() returns false? Actually, it returns true if index >= 0.
        // The array is empty, so index is 0? The context's index is managed by nextTokenToRead.
        // We'll not worry about index because our filter returns true for originally empty (contentsFiltered=false).
        // In closeArray, hasCurrentIndex() is called. For a new array context, index is -1? Let's check the code.
        // In TokenFilterContext, there is a field _index. It's initialized to -1.
        // hasCurrentIndex() returns (_index >= 0). So for an empty array, it returns false.
        // That means contentsFiltered = false, which is what we want.
        // So we can proceed.
        child.closeArray(gen);
        gen.close();
        String output = sw.toString();
        // Before patch: output would be empty (because includeEmptyArray returns false by default and no writing occurs).
        // After patch: output should be "[]".
        assertEquals("[]", output);
    }

    // Also test for objects to be thorough, but the focal method is closeArray.
    @Test
    public void testIncludeEmptyObjectGeneration() throws IOException {
        TokenFilter filter = new IncludeEmptyArraysFilter(); // includes empty objects too
        TokenFilterContext root = TokenFilterContext.createRootContext(filter);
        // Create a child object context with startHandled = false.
        TokenFilterContext child = root.createChildObjectContext(filter, false);
        // For object, we need a current name? hasCurrentName() returns true if _currentName != null.
        // In our case, we haven't set a field name, so hasCurrentName() returns false.
        // That means contentsFiltered = false (originally empty object).
        StringWriter sw = new StringWriter();
        JsonGenerator gen = new JsonFactory().createGenerator(sw);
        child.closeObject(gen);
        gen.close();
        String output = sw.toString();
        // Before patch: empty string.
        // After patch: "{}"
        assertEquals("{}", output);
    }
}

