package com.fasterxml.jackson.core.filter;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.filter.FilteringParserDelegate;
import com.fasterxml.jackson.core.filter.TokenFilter;
import com.fasterxml.jackson.core.filter.TokenFilterContext;
import com.fasterxml.jackson.core.util.JsonParserDelegate;
import org.junit.Test;

import java.io.IOException;
import java.io.StringReader;
import java.io.StringWriter;
import java.math.BigInteger;
import java.math.BigDecimal;

import static org.junit.Assert.*;

/**
 * Unit tests for the new includeEmptyArray and includeEmptyObject methods
 * in TokenFilter and their integration with FilteringParserDelegate.
 */
public class TokenFilterIncludeEmptyTest {

    // Custom TokenFilter that overrides includeEmptyArray and includeEmptyObject
    static class CustomEmptyFilter extends TokenFilter {
        private final boolean includeEmptyArray;
        private final boolean includeEmptyObject;
        private final boolean contentsFilteredParam;

        public CustomEmptyFilter(boolean includeEmptyArray, boolean includeEmptyObject) {
            this(includeEmptyArray, includeEmptyObject, false);
        }

        public CustomEmptyFilter(boolean includeEmptyArray, boolean includeEmptyObject, boolean contentsFilteredParam) {
            this.includeEmptyArray = includeEmptyArray;
            this.includeEmptyObject = includeEmptyObject;
            this.contentsFilteredParam = contentsFilteredParam;
        }

        @Override
        public boolean includeEmptyArray(boolean contentsFiltered) {
            // Verify the parameter is passed correctly
            assertEquals(contentsFilteredParam, contentsFiltered);
            return includeEmptyArray;
        }

        @Override
        public boolean includeEmptyObject(boolean contentsFiltered) {
            // Verify the parameter is passed correctly
            assertEquals(contentsFilteredParam, contentsFiltered);
            return includeEmptyObject;
        }

        @Override
        public TokenFilter includeElement(int index) {
            // Include nothing, so arrays become empty after filtering
            return null;
        }

        @Override
        public TokenFilter includeProperty(String name) {
            // Include nothing, so objects become empty after filtering
            return null;
        }
    }

    // TokenFilter that includes everything (for comparison)
    static class IncludeAllFilter extends TokenFilter {
        @Override
        public TokenFilter includeElement(int index) {
            return TokenFilter.INCLUDE_ALL;
        }

        @Override
        public TokenFilter includeProperty(String name) {
            return TokenFilter.INCLUDE_ALL;
        }
    }

    @Test
    public void testIncludeEmptyArrayDefaultBehavior() throws IOException {
        // Default TokenFilter should not include empty arrays
        TokenFilter filter = new TokenFilter();
        assertFalse(filter.includeEmptyArray(false));
        assertFalse(filter.includeEmptyArray(true));
    }

    @Test
    public void testIncludeEmptyObjectDefaultBehavior() throws IOException {
        // Default TokenFilter should not include empty objects
        TokenFilter filter = new TokenFilter();
        assertFalse(filter.includeEmptyObject(false));
        assertFalse(filter.includeEmptyObject(true));
    }

    @Test
    public void testEmptyArrayIncludedWhenFilterReturnsTrue() throws IOException {
        // JSON with an empty array
        String json = "[]";
        JsonFactory factory = new JsonFactory();
        JsonParser parser = factory.createParser(json);

        // Custom filter that includes empty arrays
        TokenFilter filter = new CustomEmptyFilter(true, false);

        FilteringParserDelegate filteringParser = new FilteringParserDelegate(parser, filter, true, false);

        // Should get START_ARRAY and END_ARRAY tokens
        assertEquals(JsonToken.START_ARRAY, filteringParser.nextToken());
        assertEquals(JsonToken.END_ARRAY, filteringParser.nextToken());
        assertNull(filteringParser.nextToken());
    }

    @Test
    public void testEmptyArrayExcludedWhenFilterReturnsFalse() throws IOException {
        // JSON with an empty array
        String json = "[]";
        JsonFactory factory = new JsonFactory();
        JsonParser parser = factory.createParser(json);

        // Custom filter that excludes empty arrays (default behavior)
        TokenFilter filter = new CustomEmptyFilter(false, false);

        FilteringParserDelegate filteringParser = new FilteringParserDelegate(parser, filter, true, false);

        // Should get no tokens since empty array is filtered out
        assertNull(filteringParser.nextToken());
    }

    @Test
    public void testEmptyObjectIncludedWhenFilterReturnsTrue() throws IOException {
        // JSON with an empty object
        String json = "{}";
        JsonFactory factory = new JsonFactory();
        JsonParser parser = factory.createParser(json);

        // Custom filter that includes empty objects
        TokenFilter filter = new CustomEmptyFilter(false, true);

        FilteringParserDelegate filteringParser = new FilteringParserDelegate(parser, filter, true, false);

        // Should get START_OBJECT and END_OBJECT tokens
        assertEquals(JsonToken.START_OBJECT, filteringParser.nextToken());
        assertEquals(JsonToken.END_OBJECT, filteringParser.nextToken());
        assertNull(filteringParser.nextToken());
    }

    @Test
    public void testEmptyObjectExcludedWhenFilterReturnsFalse() throws IOException {
        // JSON with an empty object
        String json = "{}";
        JsonFactory factory = new JsonFactory();
        JsonParser parser = factory.createParser(json);

        // Custom filter that excludes empty objects (default behavior)
        TokenFilter filter = new CustomEmptyFilter(false, false);

        FilteringParserDelegate filteringParser = new FilteringParserDelegate(parser, filter, true, false);

        // Should get no tokens since empty object is filtered out
        assertNull(filteringParser.nextToken());
    }

    @Test
    public void testArrayWithFilteredContentsBecomesEmpty() throws IOException {
        // JSON with an array that has elements, but filter excludes them all
        String json = "[1, 2, 3]";
        JsonFactory factory = new JsonFactory();
        JsonParser parser = factory.createParser(json);

        // Custom filter that excludes all elements but includes empty arrays
        TokenFilter filter = new CustomEmptyFilter(true, false, true);

        FilteringParserDelegate filteringParser = new FilteringParserDelegate(parser, filter, true, false);

        // Should get START_ARRAY and END_ARRAY tokens (empty array included)
        assertEquals(JsonToken.START_ARRAY, filteringParser.nextToken());
        assertEquals(JsonToken.END_ARRAY, filteringParser.nextToken());
        assertNull(filteringParser.nextToken());
    }

    @Test
    public void testObjectWithFilteredContentsBecomesEmpty() throws IOException {
        // JSON with an object that has properties, but filter excludes them all
        String json = "{\"a\": 1, \"b\": 2}";
        JsonFactory factory = new JsonFactory();
        JsonParser parser = factory.createParser(json);

        // Custom filter that excludes all properties but includes empty objects
        TokenFilter filter = new CustomEmptyFilter(false, true, true);

        FilteringParserDelegate filteringParser = new FilteringParserDelegate(parser, filter, true, false);

        // Should get START_OBJECT and END_OBJECT tokens (empty object included)
        assertEquals(JsonToken.START_OBJECT, filteringParser.nextToken());
        assertEquals(JsonToken.END_OBJECT, filteringParser.nextToken());
        assertNull(filteringParser.nextToken());
    }

    @Test
    public void testNestedEmptyStructures() throws IOException {
        // JSON with nested empty structures
        String json = "{\"emptyArray\": [], \"emptyObject\": {}}";
        JsonFactory factory = new JsonFactory();
        JsonParser parser = factory.createParser(json);

        // Filter that includes empty arrays but not empty objects
        TokenFilter filter = new TokenFilter() {
            @Override
            public TokenFilter includeProperty(String name) {
                // Include all properties to reach the empty structures
                return this;
            }

            @Override
            public boolean includeEmptyArray(boolean contentsFiltered) {
                return true; // Include empty arrays
            }

            @Override
            public boolean includeEmptyObject(boolean contentsFiltered) {
                return false; // Exclude empty objects
            }
        };

        FilteringParserDelegate filteringParser = new FilteringParserDelegate(parser, filter, true, false);

        // Should get: START_OBJECT, FIELD_NAME "emptyArray", START_ARRAY, END_ARRAY, END_OBJECT
        // The emptyObject field should be skipped
        assertEquals(JsonToken.START_OBJECT, filteringParser.nextToken());
        assertEquals(JsonToken.FIELD_NAME, filteringParser.nextToken());
        assertEquals("emptyArray", filteringParser.getCurrentName());
        assertEquals(JsonToken.START_ARRAY, filteringParser.nextToken());
        assertEquals(JsonToken.END_ARRAY, filteringParser.nextToken());
        assertEquals(JsonToken.END_OBJECT, filteringParser.nextToken());
        assertNull(filteringParser.nextToken());
    }

    @Test
    public void testMixedEmptyAndNonEmptyStructures() throws IOException {
        // JSON with mixed content
        String json = "{\"arr1\": [], \"arr2\": [1, 2], \"obj1\": {}, \"obj2\": {\"x\": 5}}";
        JsonFactory factory = new JsonFactory();
        JsonParser parser = factory.createParser(json);

        // Filter that includes everything (for comparison)
        TokenFilter filter = new IncludeAllFilter();

        FilteringParserDelegate filteringParser = new FilteringParserDelegate(parser, filter, true, false);

        // Parse through everything to ensure no exceptions
        int tokenCount = 0;
        while (filteringParser.nextToken() != null) {
            tokenCount++;
        }
        // Should have parsed all tokens
        assertTrue(tokenCount > 0);
    }

    @Test
    public void testContentsFilteredParameter() throws IOException {
        // Test that contentsFiltered parameter is correctly passed
        // For originally empty array, hasCurrentIndex() returns false
        // For array that becomes empty after filtering, hasCurrentIndex() returns true

        // Test 1: Originally empty array
        String json1 = "[]";
        JsonFactory factory = new JsonFactory();
        JsonParser parser1 = factory.createParser(json1);

        TokenFilter filter1 = new CustomEmptyFilter(true, false, false); // contentsFiltered should be false

        FilteringParserDelegate filteringParser1 = new FilteringParserDelegate(parser1, filter1, true, false);
        filteringParser1.nextToken(); // START_ARRAY
        filteringParser1.nextToken(); // END_ARRAY - will call includeEmptyArray(false)

        // Test 2: Array with filtered contents
        String json2 = "[1, 2]";
        JsonParser parser2 = factory.createParser(json2);

        TokenFilter filter2 = new CustomEmptyFilter(true, false, true); // contentsFiltered should be true

        FilteringParserDelegate filteringParser2 = new FilteringParserDelegate(parser2, filter2, true, false);
        filteringParser2.nextToken(); // START_ARRAY
        filteringParser2.nextToken(); // END_ARRAY - will call includeEmptyArray(true)
    }

    @Test
    public void testTokenFilterContextCloseArray() throws IOException {
        // Test generation path through TokenFilterContext.closeArray()
        JsonFactory factory = new JsonFactory();
        StringWriter sw = new StringWriter();
        JsonGenerator gen = factory.createGenerator(sw);

        // Create a context with a filter that includes empty arrays
        TokenFilter filter = new CustomEmptyFilter(true, false);
        TokenFilterContext context = TokenFilterContext.createRootContext(filter);

        // Start array but don't mark as handled (simulating filtered scenario)
        context = context.createChildArrayContext(filter, false);

        // Close array - should write empty array if filter allows
        context.closeArray(gen);
        gen.close();

        // Should have written [] if filter includes empty arrays
        assertEquals("[]", sw.toString());
    }

    @Test
    public void testTokenFilterContextCloseObject() throws IOException {
        // Test generation path through TokenFilterContext.closeObject()
        JsonFactory factory = new JsonFactory();
        StringWriter sw = new StringWriter();
        JsonGenerator gen = factory.createGenerator(sw);

        // Create a context with a filter that includes empty objects
        TokenFilter filter = new CustomEmptyFilter(false, true);
        TokenFilterContext context = TokenFilterContext.createRootContext(filter);

        // Start object but don't mark as handled (simulating filtered scenario)
        context = context.createChildObjectContext(filter, false);

        // Close object - should write empty object if filter allows
        context.closeObject(gen);
        gen.close();

        // Should have written {} if filter includes empty objects
        assertEquals("{}", sw.toString());
    }
}

